// 4. MAIN COMPONENT
const YelpReviewCard: React.FC<YelpReviewCardProps> = ({
  backgroundColor = "#ffffff", // Clean white background default
  transparentBackground = false,
  durationInSeconds = 10,
  cardColor = "#ffffff",
  starColor = "#FFD700",
  textColor = "#1a1a1a",
  accentColor = "#2E7D32",
  reviewText = "Taste is amazing—no chalk, hits different even without caffeine. Quality is top notch as always. Bucked Up is just the best. Best pump ever!",
  authorName = "Jamie S.",
  showBadge = true,
}) => {
  useFontLoader(["Open Sans"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Background Transparency Logic
  const finalBgColor = transparentBackground
    ? "transparent"
    : backgroundColor;

  // Animation Config
  const entranceStart = 10;
  
  // Card Entrance: Slide from Right + Fade In
  const cardSlide = spring({
    frame: frame - entranceStart,
    fps,
    config: { damping: 14, stiffness: 80 },
    from: 100, // Slide distance percentage
    to: 0,
  });

  const cardOpacity = spring({
    frame: frame - entranceStart,
    fps,
    config: { damping: 20 },
    from: 0,
    to: 1,
  });

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      {/* Main Content Container */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          padding: 40,
        }}
      >
        {/* Review Card */}
        <div
          style={{
            backgroundColor: cardColor,
            width: Math.min(600, width * 0.85),
            borderRadius: 20,
            padding: 40,
            boxShadow: "0 20px 40px rgba(0,0,0,0.15)", // Subtle shadow
            transform: `translateX(${cardSlide}%)`,
            opacity: cardOpacity,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            textAlign: "center",
            fontFamily: "Open Sans",
            position: "relative",
          }}
        >
          {/* Top: Stars */}
          <StarsRow color={starColor} />

          {/* Center: Quote */}
          <p
            style={{
              fontSize: 24,
              fontStyle: "italic",
              color: textColor,
              lineHeight: 1.5,
              margin: "0 0 24px 0",
            }}
          >
            "{reviewText}"
          </p>

          {/* Bottom: Author & Badge */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
            }}
          >
            <span
              style={{
                fontSize: 18,
                fontWeight: 700, // Bold
                color: textColor,
              }}
            >
              - {authorName}
            </span>

            {showBadge && <VerifiedBadge color={accentColor} />}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default YelpReviewCard;